  ta: { promise: ["வருகைகளைத் திட்டமிடுங்கள்", "உங்கள் நாள் மற்றும் மையத்திற்கு ஏற்றவாறு முன்பதிவு செய்யுங்கள்.", "முன்னேற்றத்தைப் பின்தொடருங்கள்", "உங்கள் டோக்கன் மற்றும் கொள்முதல் நிலையைப் பாருங்கள்.", "தகவலுடன் இருங்கள்", "கட்டண முன்னேற்றத்தை அறிந்து கொள்ளுங்கள்."], features: [["நிகழ்நேரத் தகவல்", "வீட்டிலிருந்து புறப்படும் முன் மைய நிலையை அறியுங்கள்."], ["ஸ்மார்ட் ஸ்லாட் ஒருங்கிணைப்பு", "மையத் திறனுக்கு ஏற்ப வருகையைத் திட்டமிடுங்கள்."], ["டிஜிட்டல் டோக்கன்", "வரிசையில் உங்கள் இடத்தைத் தெளிவாக வைத்திருங்கள்."], ["நேரடி வரிசை மற்றும் ETA", "தகவலின்றி காத்திருக்காமல் முன்னேற்றத்தைப் பாருங்கள்."], ["கொள்முதல் நிலை", "தரம், எடை மற்றும் கொள்முதல் முன்னேற்றத்தைப் பின்தொடருங்கள்."], ["கட்டண கண்காணிப்பு", "கொள்முதலுக்குப் பிந்தைய நிலையை ஒரே இடத்தில் வைத்திருங்கள்."], ["மொபைல் அணுகல்", "தேவையான தகவலை உங்கள் தொலைபேசியில் பாருங்கள்."], ["அதிகாரி பார்வை", "மையங்களுக்கு முன்பதிவுகளின் பகிரப்பட்ட பார்வையை வழங்குங்கள்."]], impact: [["குறைந்த காத்திருப்பு", "நேரத்தைத் தெளிவாக அறிந்து வருகையைத் திட்டமிடுங்கள்."], ["சிறந்த திட்டமிடல்", "அறுவடை நாளுக்கேற்ற ஸ்லாட்டைத் தேர்வு செய்யுங்கள்."], ["மேலும் தெரிவுநிலை", "வரிசை மற்றும் கொள்முதல் முன்னேற்றத்தைப் புரிந்து கொள்ளுங்கள்."], ["ஒருங்கிணைப்பு", "விவசாயிகளையும் மையங்களையும் இணைந்திருக்கச் செய்யுங்கள்."], ["வெளிப்படைத்தன்மை", "கட்டணம் வரை பயணத்தைத் தெளிவாக வைத்திருங்கள்."]], centreRows: [["தரச் சோதனை", "நடைபெறுகிறது"], ["காத்திருக்கிறது", "அடுத்தது"], ["முன்பதிவு செய்யப்பட்டது", "10:45 AM"]]},
